import type { EffinDomCallbacks } from '../../browser-bridge/src/core-types';
import {
  pushManagedHistoryEntry,
  replaceManagedHistoryEntry,
  startManagedHarness,
  type HarnessAppOptions,
  type HarnessContext,
  type HarnessController,
  type HarnessExports,
  type HarnessState,
} from './common-harness';

declare global {
  interface Window {
    __fuiAsReady?: boolean;
    __fuiAsError?: string;
    __fuiAsState?: HarnessState;
    __fuiDemoSelectionText?: string;
    __toggleDemoFoundationsScope?(): void;
    __activateDemoFoundationsScopedAction?(): void;
    __focusDemoFoundationsScopedAction?(): void;
    __getAdvancedControlsActionCount?(): number;
    __effindomCallbacks?: EffinDomCallbacks;
    __fuiDemoManagerState?: {
      readonly routePath: string;
      readonly activeWasmPath: string;
      readonly routeLoads: Readonly<Record<string, number>>;
    };
  }
}

interface DemoRouteExports extends HarnessExports {
  __runApp(): void;
  __disposeApp?(): void;
  __setDemoClockTick?(tick: number): void;
  __setDemoHue?(value: number): void;
  __setDemoDarkMode?(isDark: boolean): void;
  __toggleDemoFoundationsScope?(): void;
  __activateDemoFoundationsScopedAction?(): void;
  __focusDemoFoundationsScopedAction?(): void;
  __getAdvancedControlsActionCount?(): number;
}

interface DemoRoute {
  readonly routePath: string;
  readonly wasmPath: string;
  readonly title: string;
}

const HOME_ROUTE = '/v2/fui-as/demo/index.html';
const ADVANCED_CONTROLS_ROUTE = '/v2/fui-as/demo/advanced-controls/';
const ROUTE_BASE = '/v2/fui-as/demo/';
const ROUTES: readonly DemoRoute[] = [
  {
    routePath: HOME_ROUTE,
    wasmPath: '/v2/fui-as/demo/home.wasm?v=midnight-5',
    title: 'Dashboard',
  },
  {
    routePath: ADVANCED_CONTROLS_ROUTE,
    wasmPath: '/v2/fui-as/demo/advanced-controls.wasm?v=midnight-5',
    title: 'Advanced controls',
  },
];
const routeByPath = new Map<string, DemoRoute>(ROUTES.map((route) => [route.routePath, route]));

let activeRoute: DemoRoute | null = null;
let currentContext: HarnessContext<DemoRouteExports> | null = null;
let navigationQueue: Promise<void> = Promise.resolve();
let tick = 0;
let hue = 210;
let darkMode = window.matchMedia('(prefers-color-scheme: dark)').matches;
const routeLoads: Record<string, number> = {};

function updateOutput(id: string, value: string): void {
  const output = document.getElementById(id);
  if (output instanceof HTMLElement) {
    output.textContent = value;
  }
}

function normalizeRoutePath(pathname: string): string {
  if (pathname === ROUTE_BASE || pathname === '/v2/fui-as/demo') {
    return HOME_ROUTE;
  }
  if (pathname === HOME_ROUTE) {
    return HOME_ROUTE;
  }
  if (pathname === ADVANCED_CONTROLS_ROUTE || pathname === `${ADVANCED_CONTROLS_ROUTE}index.html`) {
    return ADVANCED_CONTROLS_ROUTE;
  }
  if (pathname.endsWith('/advanced-controls/index.html')) {
    return ADVANCED_CONTROLS_ROUTE;
  }
  return HOME_ROUTE;
}

function resolveRoute(pathname: string): DemoRoute {
  return routeByPath.get(normalizeRoutePath(pathname)) ?? ROUTES[0];
}

function currentBrowserRoute(): DemoRoute {
  return resolveRoute(window.location.pathname);
}

function sameBrowserLocation(route: DemoRoute): boolean {
  return currentBrowserRoute().routePath === route.routePath;
}

function updateThemeControls(): void {
  document.documentElement.dataset.demoTheme = darkMode ? 'dark' : 'light';
  document.documentElement.style.colorScheme = darkMode ? 'dark' : 'light';
  updateOutput('theme-mode-value', darkMode ? 'Dark' : 'Light');
  const themeButton = document.getElementById('toggle-theme-mode');
  if (themeButton instanceof HTMLButtonElement) {
    themeButton.textContent = darkMode ? 'Switch to light mode' : 'Switch to dark mode';
  }
}

function applyRouteSpecificControls(context: HarnessContext<DemoRouteExports> | null): void {
  const exports = context?.exports;
  exports?.__setDemoHue?.(hue);
  exports?.__setDemoDarkMode?.(darkMode);
  exports?.__setDemoClockTick?.(tick);
  window.__toggleDemoFoundationsScope = () => {
    exports?.__toggleDemoFoundationsScope?.();
  };
  window.__activateDemoFoundationsScopedAction = () => {
    exports?.__activateDemoFoundationsScopedAction?.();
  };
  window.__focusDemoFoundationsScopedAction = () => {
    exports?.__focusDemoFoundationsScopedAction?.();
  };
  window.__getAdvancedControlsActionCount = () => {
    return exports?.__getAdvancedControlsActionCount?.() ?? -1;
  };
}

function syncManagerState(route: DemoRoute): void {
  window.__fuiDemoManagerState = {
    routePath: route.routePath,
    activeWasmPath: route.wasmPath,
    routeLoads: { ...routeLoads },
  };
}

async function navigateToRoute(
  controller: HarnessController,
  targetUrl: URL,
  mode: 'push' | 'replace' | 'pop',
): Promise<void> {
  const route = resolveRoute(targetUrl.pathname);
  if (mode !== 'pop' && sameBrowserLocation(route) && activeRoute?.routePath === route.routePath) {
    syncManagerState(route);
    window.__fuiAsReady = true;
    delete window.__fuiAsError;
    return;
  }

  const destination = new URL(route.routePath, window.location.origin);
  destination.search = targetUrl.search;
  destination.hash = targetUrl.hash;
  if (mode === 'push') {
    pushManagedHistoryEntry(destination);
  } else if (mode === 'replace' && !sameBrowserLocation(route)) {
    replaceManagedHistoryEntry(destination);
  }

  window.__fuiAsReady = false;
  const isWarmRouteSwap = activeRoute !== null;
  if (isWarmRouteSwap) {
    await controller.recreateRuntime();
  }

  const appOptions: HarnessAppOptions<DemoRouteExports> = {
    wasmPath: route.wasmPath,
    showLoadingOverlay: !isWarmRouteSwap,
    run(exports): void {
      exports.__runApp();
    },
    onDispose(exports): void {
      exports.__disposeApp?.();
    },
    onStateUpdated(state): void {
      window.__fuiAsState = state;
    },
  };

  const context = await controller.loadApp(appOptions);
  currentContext = context;
  routeLoads[route.routePath] = (routeLoads[route.routePath] ?? 0) + 1;
  activeRoute = route;
  applyRouteSpecificControls(context);
  syncManagerState(route);
  window.__fuiAsReady = true;
  delete window.__fuiAsError;
}

startManagedHarness({
  onReady: async (controller): Promise<void> => {
    const hueInput = document.getElementById('hue') as HTMLInputElement | null;
    const pulseButton = document.getElementById('pulse-hue');
    const themeButton = document.getElementById('toggle-theme-mode');
    const callbacks: EffinDomCallbacks = window.__effindomCallbacks ?? {};
    const previousCrossSelectionChanged = callbacks.onCrossSelectionChanged;
    callbacks.onCrossSelectionChanged = (handle, text) => {
      previousCrossSelectionChanged?.(handle, text);
      window.__fuiDemoSelectionText = text;
    };
    window.__effindomCallbacks = callbacks;

    if (hueInput !== null) {
      hueInput.value = String(hue);
      hueInput.addEventListener('input', () => {
        hue = Number(hueInput.value);
        updateOutput('hue-value', `${String(hue)} deg`);
        applyRouteSpecificControls(currentContext);
      });
    }

    if (pulseButton instanceof HTMLElement) {
      pulseButton.addEventListener('click', () => {
        hue = (tick * 47 + 120) % 360;
        if (hueInput !== null) {
          hueInput.value = String(hue);
        }
        updateOutput('hue-value', `${String(hue)} deg`);
        applyRouteSpecificControls(currentContext);
      });
    }

    if (themeButton instanceof HTMLElement) {
      themeButton.addEventListener('click', () => {
        darkMode = !darkMode;
        updateThemeControls();
        applyRouteSpecificControls(currentContext);
      });
    }

    updateOutput('hue-value', `${String(hue)} deg`);
    updateOutput('tick-value', '0 s');
    updateThemeControls();
    window.__fuiDemoSelectionText = '';

    window.setInterval(() => {
      tick += 1;
      updateOutput('tick-value', `${String(tick)} s`);
      currentContext?.exports.__setDemoClockTick?.(tick);
    }, 1000);

    controller.setSameOriginNavigationHandler((target, mode) => {
      navigationQueue = navigationQueue.then(() => navigateToRoute(controller, target, mode));
      return navigationQueue;
    });

    await navigateToRoute(controller, new URL(window.location.href), 'replace');
  },
  onError(error): void {
    window.__fuiAsError = error instanceof Error ? error.message : String(error);
  },
});
